"""Evaluation helpers.  Labels are consumed only here, after scores exist (R9, R10)."""

from __future__ import annotations

from typing import Dict, Iterable, List

import numpy as np
from sklearn.metrics import average_precision_score, precision_recall_curve, roc_auc_score

__all__ = ["auc_roc", "auc_pr", "auc_pr_trapz", "summarize"]


def auc_roc(scores: np.ndarray, y: np.ndarray) -> float:
    """AUC-ROC of ``scores`` against binary labels ``y`` (R9)."""
    return float(roc_auc_score(np.asarray(y).astype(int), np.asarray(scores, dtype=np.float64)))


def auc_pr(scores: np.ndarray, y: np.ndarray) -> float:
    """AUC-PR via the step-function (rank) definition, the ADBench convention (R9)."""
    return float(
        average_precision_score(np.asarray(y).astype(int), np.asarray(scores, dtype=np.float64))
    )


def auc_pr_trapz(scores: np.ndarray, y: np.ndarray) -> float:
    """AUC-PR as the trapezoidal area under the precision-recall curve (secondary)."""
    p, r, _ = precision_recall_curve(
        np.asarray(y).astype(int), np.asarray(scores, dtype=np.float64)
    )
    return float(np.trapezoid(p, r))


def summarize(values: Iterable[float]) -> Dict[str, float]:
    """mean / std / min / max over the repeated runs (R8)."""
    v = np.asarray(list(values), dtype=np.float64)
    return {
        "mean": float(v.mean()),
        "std": float(v.std(ddof=1)) if v.size > 1 else 0.0,
        "min": float(v.min()),
        "max": float(v.max()),
        "n": int(v.size),
    }

